import Config

config :opentelemetry, traces_exporter: :none

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :sdr_agent, SdrAgentWeb.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"

# The hosted copy admits only users on SDR_LOGIN_ALLOWLIST at every sign-in
# and session (`SdrAgent.Accounts.LoginAllowlist`; fail closed).
config :sdr_agent, login_allowlist_enforced: true

# Force using SSL in production. This also sets the "strict-security-transport" header,
# known as HSTS. If you have a health check endpoint, you may want to exclude it below.
# Note `:force_ssl` is required to be set at compile-time.
config :sdr_agent, SdrAgentWeb.Endpoint,
  force_ssl: [
    rewrite_on: [:x_forwarded_proto],
    exclude: [
      # paths: ["/health"],
      hosts: ["localhost", "127.0.0.1"]
    ]
  ]

# Configure Swoosh API Client
# Outreach delivers only through the local capture adapter (ADR-0001: no
# outreach delivery path can reach a real recipient; S8 asserts it). The
# HTTP client exists in prod for one sender only: the hosted owner's
# magic-link sign-in mail through Postmark (config/runtime.exs, only with
# POSTMARK_API_KEY; only to addresses on SDR_LOGIN_ALLOWLIST). Dev and test
# have no HTTP mail client.
config :swoosh, api_client: Swoosh.ApiClient.Req

# Disable Swoosh Local Memory Storage
config :swoosh, local: false

# Do not print debug messages in production
config :logger, level: :info

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.

# The hosted copy runs no follow-up (`SdrAgent.Outreach.FollowUps`; D-218
# item 9 containment until the D-206 suppression fix lands): no follow-up job
# is scheduled and a queued one is cancelled before any read. Only dev and
# test enable them; a missing setting is disabled too (fail closed).
# `scripts/deploy.sh` checks this release setting and the store
# (`SdrAgent.Release.verify_hosted_containment/0`) before switching.
config :sdr_agent, :follow_ups, :disabled
